import { Button } from '@refy-design/web';
import { Drawer } from '@refy-design/web';
import { HelpMenu } from '@refy-design/web';
import { Textarea } from '@refy-design/web';
import { useState } from 'react';
const stack = { display: 'grid', gap: 'var(--space-4)', minWidth: 0 } as const;
function HelpMenuExample() {
  const [panel, setPanel] = useState(''),
    [message, setMessage] = useState(''),
    [sent, setSent] = useState(false);
  return (
    <>
      <HelpMenu
        onSelect={(id) => {
          setSent(false);
          setPanel(id);
        }}
      />
      <Drawer
        open={Boolean(panel)}
        onOpenChange={(open) => {
          if (!open) setPanel('');
        }}
        title={
          panel === 'docs'
            ? 'Documentation'
            : panel === 'shortcuts'
              ? 'Keyboard shortcuts'
              : 'Sample support'
        }
      >
        {panel === 'docs' ? (
          <>
            <h3>How to use the component</h3>
            <p>
              Choose a menu option. In your product, point it to the matching
              documentation.
            </p>
          </>
        ) : panel === 'shortcuts' ? (
          <dl>
            <dt>Arrows</dt>
            <dd>Move through menu options</dd>
            <dt>Enter</dt>
            <dd>Choose an option</dd>
            <dt>Escape</dt>
            <dd>Close the current layer</dd>
          </dl>
        ) : sent ? (
          <p role="status">Message logged locally. Nothing was sent.</p>
        ) : (
          <form
            style={stack}
            onSubmit={(e) => {
              e.preventDefault();
              if (message.trim()) setSent(true);
            }}
          >
            <Textarea
              label="How can we help?"
              required
              value={message}
              onChange={(e) => setMessage(e.target.value)}
            />
            <Button type="submit">Log sample message</Button>
          </form>
        )}
      </Drawer>
    </>
  );
}
export function Example() {
  return <HelpMenuExample />;
}
